from pathlib import Path
import json,hashlib,statistics
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def load(p):return json.loads(Path(p).read_text())
def save(p,v):Path(p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
BEST='r1_station_only';folder=HERE/'results'/(BEST+'_exposed');summary=load(folder/'summary.json')
rows=load(folder/'case_metrics.json');refs=load(ROOT/'experiments/20260911_stage4/baseline/expected_rows.json');bi={r['case_id']:r for r in refs}
combined=[r for r in summary['comparisons_to_S1'] if r['suite']=='combined' and r['group']=='ALL']
