for row in rows:
 base=bi[row['case_id']];d=row['average_clear_time_s']-base['average_clear_time_s']
 if d>1e-8:reg.append(dict(case_id=row['case_id'],mode=row['mode'],group=row['group'],suite=row['exposure_suite'],delta_s_per_source=d,source_count=row['source_count'],candidate_s=row['total_virtual_time_s'],baseline_s=base['total_virtual_time_s'],distance_delta_m=row['distance_m']-base['distance_m'],clear_failure_delta=row['clear_failures']-base['clear_failures']))
