best=dict(current=BEST,candidate=str((HERE/'snapshots'/(BEST+'.py')).relative_to(ROOT)),sha256=summary['candidate_sha256'],deployment_dependencies={},
  q3_mean_s_per_source=combined[0]['candidate_mean_s_per_source'],q4_mean_s_per_source=combined[1]['candidate_mean_s_per_source'],
  all_complete=summary['all_complete'],result_path=str(folder.relative_to(ROOT)),data_role='4800 exposed local regression',comparisons_to_S1=combined,
  previous_full_candidate='r1_cost_all',comparisons_to_previous=[r for r in summary['comparisons_to_previous'] if r['suite']=='combined' and r['group']=='ALL'])
